    const signal = init && init.signal;
    calls.push({
      url,
      signal,
      respond: (status, body) => resolve({ ok: status >= 200 && status < 300, status, json: async () => body }),
      fail: (err) => reject(err),
    });
    if (signal) signal.addEventListener('abort', () => reject(new DOMException('aborted', 'AbortError')));
  });
