function useCounter({ initial = 0, min = -Infinity, max = Infinity, step = 1 } = {}) {
  const clamp = useCallback((n) => Math.min(max, Math.max(min, n)), [min, max]);
  const [count, setCount] = useState(() => clamp(initial));
